1	//! The agent-layer search budget: cuts a fully ranked, uncapped result down to what one response may carry.
2	//!
3	//! Core returns every ranked block and holds no caps; this module is the first thing a caller does with that result.
4	use michi::TruncationOutcome;
5	
6	use crate::types::{Diagnostic, RankedBlock, SearchLimits, SearchResponse};
7	
8	/// Texts longer than this many bytes are measured by their byte length instead of being tokenized.
9	///
10	/// BPE merging is quadratic in the length of an unbroken pretoken (200 KB of one run takes seconds), so minified
11	/// bundles and base64 blobs must not reach the tokenizer. Byte length is a proven upper bound on the token count, so
12	/// the fallback can only make a block look larger, never let one overspend the budget.
13	const TOKENIZE_BYTE_CAP: usize = 32 * 1024;
14	
15	const GUIDANCE: &str = "refine the query with +term or -term";
16	
17	/// The three caps one search response must stay within.
18	///
19	/// # Examples
20	///
21	/// ```
22	/// use monokl::budget::Budget;
23	///
24	/// let budget = Budget::default();
25	/// assert_eq!((budget.max_results, budget.max_tokens, budget.max_bytes), (50, 20_000, 2_097_152));
26	/// ```
27	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
28	pub struct Budget {
29	    /// The most blocks a response may carry.
30	    pub max_results: usize,
31	    /// The most tokens (`o200k_base`) the kept blocks' code may total.
32	    pub max_tokens: usize,
33	    /// The most bytes the kept blocks' code may total.
34	    pub max_bytes: usize,
35	}
36	
37	impl Default for Budget {
38	    fn default() -> Self {
39	        Self { max_results: 50, max_tokens: 20_000, max_bytes: 2_097_152 }
40	    }
41	}
42	
43	impl From<&SearchLimits> for Budget {
44	    /// Fills an unset result or token cap with the default and clamps the byte cap to the 2 MiB ceiling.
45	    fn from(limits: &SearchLimits) -> Self {
46	        let default = Self::default();
47	        Self {
48	            max_results: limits.max_results.unwrap_or(default.max_results),
49	            max_tokens: limits.max_tokens.unwrap_or(default.max_tokens),
50	            max_bytes: limits.max_bytes.min(default.max_bytes),
51	        }
52	    }
53	}
54	
55	/// Returns the `o200k_base` token count of `text`, or its byte length when it is over the tokenizer's byte cap.
56	///
57	/// The byte length is an upper bound on the token count, so the count never understates.
58	///
59	/// # Examples
60	///
61	/// ```
62	/// use monokl::budget::count_tokens;
63	///
64	/// assert_eq!(count_tokens(""), 0);
65	/// assert_eq!(count_tokens("hello world"), 2);
66	/// ```
67	pub fn count_tokens(text: &str) -> usize {
68	    if text.len() > TOKENIZE_BYTE_CAP {
69	        return text.len();
70	    }
71	    tiktoken_rs::o200k_base_singleton().encode_with_special_tokens(text).len()
72	}
73	
74	/// Keeps the longest rank-order prefix of `ranked` that fits `budget` and reports what was cut.
75	///
76	/// Blocks are never split or reordered. The cut falls at the first block that would break any of the three caps, so a
77	/// block larger than the whole byte budget leaves no results. `total_before` is the count the caller had before any
78	/// cap, which may exceed `ranked.len()` when an earlier stage already dropped candidates; the response is truncated
79	/// whenever fewer blocks are kept than that. `total_bytes` sums the kept blocks' code length and `total_tokens` its
80	/// [`count_tokens`] count. `diagnostics` pass through untouched.
81	///
82	/// # Examples
83	///
84	/// ```
85	/// use monokl::budget::{apply_budget, Budget};
86	///
87	/// let response = apply_budget(Vec::new(), 0, &Budget::default(), Vec::new());
88	/// assert!(!response.truncated);
89	/// assert_eq!(response.truncation_marker, None);
90	/// ```
91	pub fn apply_budget(
92	    ranked: Vec<RankedBlock>,
93	    total_before: usize,
94	    budget: &Budget,
95	    diagnostics: Vec<Diagnostic>,
96	) -> SearchResponse {
97	    let mut kept = Vec::new();
98	    let mut total_bytes = 0usize;
99	    let mut total_tokens = 0usize;
100	    for block in ranked {
101	        if kept.len() >= budget.max_results {
102	            break;
103	        }
104	        let bytes = block.block.code.len();
105	        let Some(next_bytes) = total_bytes.checked_add(bytes).filter(|b| *b <= budget.max_bytes) else { break };
106	        let tokens = count_tokens(&block.block.code);
107	        let Some(next_tokens) = total_tokens.checked_add(tokens).filter(|t| *t <= budget.max_tokens) else { break };
108	        total_bytes = next_bytes;
109	        total_tokens = next_tokens;
110	        kept.push(block);
111	    }
112	
113	    let outcome = TruncationOutcome::new(kept, total_before);
114	    let truncation_marker = outcome.hint(GUIDANCE).map(|hint| hint.as_str().to_owned());
115	    SearchResponse {
116	        total_blocks_before_truncation: outcome.total_before,
117	        truncated: outcome.truncated(),
118	        truncation_marker,
119	        results: outcome.kept,
120	        total_bytes,
121	        total_tokens,
122	        diagnostics,
123	    }
124	}
